put('components/Treatments.tsx', ''''use client';
import {useRef,useState} from 'react';import Link from 'next/link';import gsap from 'gsap';import {categories,slugify} from '@/lib/services';import Photo from './Photo';
const collections=[{index:0,name:'Skin & Facials',image:'treatment-facial',title:'The skin you’re in.'},{index:1,name:'Injectables & Aesthetics',image:'treatment-aesthetic',title:'Your features. Your way.'},{index:3,name:'Laser & Corrective',image:'treatment-laser',title:'A considered approach.'},{index:2,name:'Hair Restoration',image:'hair-study',title:'A new conversation.'},{index:4,name:'Wellness & Nutrition',image:'nutrition-study',title:'Care beyond the surface.'},{index:5,name:'Bridal Preparation',image:'bridal-study',title:'For your next chapter.'}];
export default function Treatments(){const [active,setActive]=useState(0);const panel=useRef<HTMLDivElement>(null);const tween=useRef<gsap.core.Tween|null>(null);const c=collections[active],data=categories[c.index];function select(i:number){setActive(i);if(panel.current&&!matchMedia('(prefers-reduced-motion: reduce)').matches){tween.current?.kill();tween.current=gsap.fromTo(panel.current,{opacity:.35,y:12},{opacity:1,y:0,duration:.65,ease:'power2.out',clearProps:'transform,opacity'})}}return <section className="collection" id="collection"><div className="collection-heading"><div><span className="kicker">02 / THE TREATMENT COLLECTION</span><h2>Find your<br/><em>point of difference.</em></h2></div><p>Six perspectives on personal care.<br/>One starting point: you.</p></div><div className="collection-tabs" role="tablist" aria-label="Treatment collections">{collections.map((x,i)=><button key={x.name} id={`collection-tab-${i}`} role="tab" aria-selected={active===i} aria-controls="collection-panel" tabIndex={active===i?0:-1} onClick={()=>select(i)} onKeyDown={e=>{let n=i;if(e.key==='ArrowRight')n=(i+1)%6;else if(e.key==='ArrowLeft')n=(i+5)%6;else if(e.key==='Home')n=0;else if(e.key==='End')n=5;else return;e.preventDefault();select(n);document.getElementById(`collection-tab-${n}`)?.focus()}}><span>0{i+1}</span>{x.name}<b>↗</b></button>)}</div><div ref={panel} className={`collection-stage collection-${active}`} id="collection-panel" role="tabpanel" aria-labelledby={`collection-tab-${active}`}><Photo name={c.image}/><div className="collection-scrim"/><div className="stage-heading"><span className="kicker">REVIVE / {c.name.toUpperCase()}</span><h3>{c.title}</h3><p>{data.description}</p><span className="stage-photo-note">ILLUSTRATIVE EDITORIAL PHOTOGRAPHY</span></div><div className="stage-services"><span className="kicker">EXPLORE THIS COLLECTION</span>{data.services.map(s=><Link href={`/treatments/${slugify(s)}`} key={s}>{s}<span>↗</span></Link>)}<Link href="/treatments" className="all-services">The complete treatment directory ↗</Link></div><span className="stage-number" aria-hidden="true">0{active+1}</span></div><div className="collection-foot"><p>Individual suitability is assessed during consultation. Results and recovery vary.</p><Link href="/contact">Not sure where to begin? Let’s talk ↗</Link></div></section>}
''')
put('components/Consultation.tsx', ''''use client';
import {useState} from 'react';import Link from 'next/link';
const steps=[{title:'Tell us your story.',text:'Contact the clinic to discuss what you have in mind, confirm the consulting practitioner and enquire about appointment availability.',detail:'A concern is enough. You do not need to choose a procedure before speaking with us.'},{title:'Explore your options.',text:'Use your consultation to discuss your concerns, medical history, suitability and possible approaches. Ask about alternatives, risks, recovery and the full cost.',detail:'Bring your current medicines, skincare routine and details of previous procedures.'},{title:'Decide in your own time.',text:'Consider the information, ask further questions and agree on a next step only when you feel informed. A consultation does not commit you to a procedure.',detail:'Your plan may include treatment, further assessment, an alternative or no procedure.'}];
export default function Consultation(){const [active,setActive]=useState(0);return <section className="consultation-section"><div className="consultation-title"><span className="kicker">05 / YOUR FIRST CHAPTER</span><h2>No rush.<br/>Just a <em>conversation.</em></h2><Link className="button" href="/contact">Request a consultation <span>↗</span></Link></div><div className="consultation-interactive"><div className="step-buttons" role="tablist" aria-label="Consultation steps">{steps.map((s,i)=><button key={s.title} id={`step-${i}`} role="tab" aria-selected={active===i} aria-controls="step-content" onClick={()=>setActive(i)}>0{i+1}<span>{['Connect','Consult','Consider'][i]}</span></button>)}</div><div className="step-content" id="step-content" role="tabpanel" aria-labelledby={`step-${active}`}><span className="step-big" aria-hidden="true">0{active+1}</span><h3>{steps[active].title}</h3><p>{steps[active].text}</p><p className="step-detail">{steps[active].detail}</p></div></div></section>}
''')
put('components/Motion.tsx', ''''use client';
import gsap from 'gsap';import {ScrollTrigger} from 'gsap/ScrollTrigger';import {useGSAP} from '@gsap/react';gsap.registerPlugin(ScrollTrigger,useGSAP);
export default function Motion(){useGSAP(()=>{const mm=gsap.matchMedia();mm.add('(prefers-reduced-motion: no-preference)',()=>{const intro=gsap.timeline({defaults:{ease:'power3.out'}});intro.from('.cinema-image',{scale:1.08,clipPath:'inset(5% 3% 5% 3%)',duration:1.5},0).from('.hero-line',{y:35,opacity:0,stagger:.1,duration:1},.05).from('.header',{y:-12,opacity:0,duration:.7},0);gsap.from('.identity-inset',{clipPath:'inset(10% 0 10% 0)',duration:1.1,scrollTrigger:{trigger:'.identity-inset',start:'top 90%',once:true}});const scene=gsap.timeline({scrollTrigger:{trigger:'.perspective-scene',start:'top 85%',end:'bottom 20%',scrub:1}});scene.fromTo('.orbit-one',{rotate:-30,scale:.75},{rotate:35,scale:1.15},0).fromTo('.orbit-two',{rotate:40},{rotate:-35},0).fromTo('.orbit-three',{rotate:-15,y:70},{rotate:20,y:-70},0).fromTo('.scene-word',{opacity:.25,y:30},{opacity:1,y:0,stagger:.2},.15);gsap.to('.cinema-image img',{yPercent:8,ease:'none',scrollTrigger:{trigger:'.cinema-hero',start:'top top',end:'bottom top',scrub:1}})});return()=>mm.revert()},[]);return null}
''')
put('components/Photo.tsx', '''import Image from 'next/image';
const aliases:Record<string,string>={portrait:'journal-portrait',skin:'journal-care',still:'nutrition-study'};
const descriptions:Record<string,string>={'care-hero':'A facial application in progress — illustrative stock, not a Revive treatment photograph','skin-study':'Aesthetic skin care detail — illustrative stock, not a Revive patient','nutrition-study':'Fresh food ingredients — illustrative nutrition photography','treatment-facial':'Facial treatment detail — illustrative stock photography','treatment-aesthetic':'Natural facial features — illustrative editorial portrait','treatment-laser':'Clinical equipment study — illustrative stock photography'};
export default function Photo({name='portrait',className='',priority=false}:{name?:string;className?:string;priority?:boolean}){const file=aliases[name]||name;return <div className={`photo ${className}`}><Image src={`/images/${file}.jpg`} alt={descriptions[file]||'Editorial study — stock photography, not Revive staff, premises or patient results'} fill sizes="(max-width: 768px) 100vw, 80vw" priority={priority}/></div>}
''')
